insert into public.recipes (id, name, meal_type, description, prep_min, kcal, protein, carbs, fat, ingredients, steps, tags, image_url) values
(md5('recipe:Garlic butter sirloin steak with potatoes and beans')::uuid,'Garlic butter sirloin steak with potatoes and beans','dinner','Seared sirloin basted in garlic and thyme butter, with baby potatoes and green beans.',30,567,47.6,31.9,28.4,array['200 g sirloin steak','1/2 tbsp olive oil','10 g butter','1 clove garlic, crushed','1 sprig fresh thyme','150 g baby potatoes, boiled','75 g green beans','1/2 tsp lemon juice','salt and black pepper to taste']::text[],array['Take the steak out of the fridge 30 minutes early, pat it dry and season both sides.','Boil the potatoes for 12 minutes, adding the beans for the last 3 minutes, then drain.','Sear the steak in a very hot pan with the oil for 3 minutes per side for medium-rare.','Add the butter, garlic and thyme and spoon the foaming butter over the steak for 1 minute.','Rest for 5 minutes, slice, and toss the beans and potatoes with the lemon juice.']::text[],array['high protein','classic']::text[],null),
(md5('recipe:Steak and sweet potato bowl with chimichurri')::uuid,'Steak and sweet potato bowl with chimichurri','lunch','Sliced rump steak on spinach and roasted sweet potato with a fresh herb chimichurri.',35,657,48.2,36.7,36.8,array['200 g rump steak','1 tsp olive oil','1/4 tsp smoked paprika','150 g sweet potato, cubed','50 g baby spinach','35 g avocado','15 g fresh parsley','1/2 clove garlic','1 tbsp olive oil (for the chimichurri)','1/2 tbsp red wine vinegar','pinch of chilli flakes','salt to taste']::text[],array['Roast the sweet potato with a little oil and salt at 200C for 25 minutes.','Blend or finely chop the parsley, garlic, olive oil, vinegar and chilli flakes into a chimichurri.','Rub the steak with oil, paprika and salt, sear 3 to 4 minutes per side and rest for 5 minutes.','Slice the steak and serve over the spinach and sweet potato with the avocado and chimichurri.']::text[],array['high protein','meal prep']::text[],null),
(md5('recipe:Steak fajita wraps')::uuid,'Steak fajita wraps','lunch','Sizzling steak strips and peppers in warm tortillas with salsa, yogurt and cheese.',25,679,48.1,56,29,array['150 g flank or rump steak, cut into strips','1/2 red pepper','1/2 green pepper','50 g red onion','1/2 tbsp olive oil','1 tsp fajita seasoning','1 tbsp lime juice','2 small flour tortillas','30 g Greek yogurt 0% fat','20 g salsa','15 g cheddar cheese','fresh coriander']::text[],array['Toss the steak strips in half the oil and the seasoning.','Fry the peppers and onion in the rest of the oil over high heat for 5 minutes and set aside.','Sear the steak strips for 2 to 3 minutes until browned, then return the vegetables and add the lime juice.','Warm the tortillas and fill with steak and veg, topped with yogurt, salsa, cheese and coriander.']::text[],array['high protein','mexican']::text[],null),
(md5('recipe:Black pepper steak stir-fry')::uuid,'Black pepper steak stir-fry','dinner','Quick wok-fried sirloin with crunchy vegetables in a peppery soy and oyster sauce.',25,491,40.4,49,15.2,array['150 g sirloin steak, thinly sliced','1 tbsp soy sauce','1/2 tsp cornflour','1 tsp olive oil','1/2 tbsp black peppercorns, coarsely crushed','1/2 red pepper, sliced','50 g mangetout','50 g broccoli florets','1 clove garlic, sliced','1/2 tsp grated fresh ginger','1/2 tbsp oyster sauce','1/2 tsp honey','100 g basmati rice, cooked']::text[],array['Mix the steak with half the soy sauce and the cornflour and leave for 10 minutes.','Stir-fry the steak in a smoking hot wok for 1 to 2 minutes and set aside.','Stir-fry the vegetables, garlic, ginger and pepper for 3 minutes.','Return the steak, add the oyster sauce, remaining soy sauce and honey and toss for 1 minute. Serve over the rice.']::text[],array['high protein','asian']::text[],null),
(md5('recipe:Steak salad with blue cheese and walnuts')::uuid,'Steak salad with blue cheese and walnuts','lunch','Sliced medium-rare sirloin on a crisp salad with blue cheese, walnuts and balsamic dressing.',20,539,46.7,14.7,33.6,array['180 g sirloin steak','1/2 tsp olive oil','50 g mixed salad leaves','75 g cherry tomatoes, halved','75 g cucumber, sliced','25 g red onion, thinly sliced','20 g blue cheese','10 g walnuts','1/2 tbsp olive oil (dressing)','1/2 tbsp balsamic vinegar','1/2 tsp Dijon mustard','1/2 tsp honey','salt and black pepper to taste']::text[],array['Rub the steak with oil, salt and pepper and sear for 3 minutes per side for medium-rare, then rest for 5 minutes.','Whisk the olive oil, balsamic, mustard and honey into a dressing.','Toss the leaves, tomatoes, cucumber and onion with half the dressing.','Slice the steak across the grain over the salad, add the blue cheese and walnuts and drizzle with the rest of the dressing.']::text[],array['high protein','low carb']::text[],null),
(md5('recipe:Asian steak lettuce wraps')::uuid,'Asian steak lettuce wraps','lunch','Sliced steak in a soy, lime and sweet chilli glaze, piled into crisp lettuce cups with fresh veg.',20,343,35.5,16.1,16.1,array['150 g rump or sirloin steak','1/2 tsp sesame oil','1/2 tsp vegetable oil','1 clove garlic, minced','1/2 tsp grated fresh ginger','1/2 tbsp soy sauce','1/2 tbsp sweet chilli sauce','1/2 tbsp lime juice','40 g carrot, grated','50 g cucumber, thinly sliced','1 spring onion, sliced','4 butter lettuce leaves','1/2 tbsp sesame seeds','fresh coriander','1/2 red chilli, sliced (optional)']::text[],array['Mix the soy sauce, sweet chilli sauce, lime juice and sesame oil.','Sear the whole steak in the vegetable oil for 3 minutes per side, adding the garlic and ginger for the last 30 seconds. Rest for 5 minutes and slice thinly.','Toss the sliced steak in the sauce.','Spoon into the lettuce leaves and top with carrot, cucumber, spring onion, sesame seeds, coriander and chilli.']::text[],array['high protein','low carb']::text[],null),
(md5('recipe:Slow-cooked steak and bean chilli')::uuid,'Slow-cooked steak and bean chilli','dinner','Tender braising steak and kidney beans in a smoky tomato chilli, served on brown rice.',75,842,66.7,81.9,27.4,array['200 g braising steak, cut into chunks','1/2 tbsp olive oil','60 g onion','75 g red pepper','1 clove garlic, crushed','1 tsp smoked paprika','1 tsp ground cumin','1/2 tsp chilli powder','1/2 tbsp tomato purée','200 g chopped tomatoes, canned','100 ml beef stock','120 g kidney beans, canned, drained','160 g brown rice, cooked','30 g Greek yogurt 0% fat','10 g cheddar cheese','fresh coriander','salt to taste']::text[],array['Brown the beef in the oil in batches over high heat and set aside.','Soften the onion and pepper for 5 minutes, then add the garlic, spices and tomato purée and cook for 1 minute.','Return the beef, add the tomatoes, stock and salt and simmer gently with a lid on for 50 minutes.','Add the beans and simmer uncovered for 10 minutes until thick. Serve on the rice with yogurt, cheddar and coriander.']::text[],array['meal prep','comfort']::text[],null)
